(()=>{'use strict';
 const C=FishbotCore,B=FishbotBridge,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const paths={menu:'M4 6h16M4 12h16M4 18h16',chat:'M21 11a9 9 0 0 1-9 9 9 9 0 0 1-4-.9L3 21l1.8-5A9 9 0 1 1 21 11Z',bots:'M8 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0ZM4 21v-2a6 6 0 0 1 12 0v2m3-12a3 3 0 0 1 0 6m2 6v-2a5 5 0 0 0-3-4',memory:'M12 5c-4-4-9 0-7 4-5 3-2 8 1 8 0 5 6 5 6 1V5Zm0 0c4-4 9 0 7 4 5 3 2 8-1 8 0 5-6 5-6 1',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Zm7 9a4 4 0 1 0-8 0 4 4 0 0 0 8 0',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',arrow:'M12 19V5m-6 6 6-6 6 6',stop:'M6 6h12v12H6Z',file:'M14 2H5v20h14V7Zm0 0v6h6M8 12h8m-8 4h6',more:'M5 12h.01M12 12h.01M19 12h.01',back:'m14 5-7 7 7 7',check:'m5 12 4 4L19 6',history:'M3 4v6h6M3 10a9 9 0 1 1 2 8m7-11v5l3 2',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1m-2 7a5 5 0 1 1-10 0 5 5 0 0 1 10 0'};
 const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.chat}"/></svg>`;
 let state,engine,page='chat',filter='',memoryTab='list',selectedMemory=null,reading=false,toastTimer,queue=Promise.resolve();const drafts=new Map(),pending=new Map();
 const bot=()=>state.bots.find(b=>b.id===state.activeId),avatar=b=>b?.id===state.supervisorId?'<span class="avatar whale"><img src="whale.svg" alt=""></span>':`<span class="avatar ${C.shapes.includes(b?.shape)?b.shape:b?.type==='group'?'group':'circle'} ${C.colors.includes(b?.color)?b.color:'gray'}"><span>${esc(b?.type==='group'?'群':(b?.name||'Bot').slice(0,1))}</span></span>`;
 const date=at=>new Date(at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}),files=()=>pending.get(state.activeId)||[];
 function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
 function save(){const snapshot=C.exportData(state);queue=queue.catch(()=>{}).then(()=>B.save(snapshot));return queue;}
 async function attempt(fn){try{return await fn();}catch(e){toast(e.name==='AbortError'?'已停止。':e.message||'未能完成，请重试。');}}
 function appearance(){document.documentElement.dataset.theme=state.config.theme;document.body.classList.toggle('reduced',state.config.reducedMotion);B.appearance(state.config.theme);}
 function card(f,remove=false){return `<div class="file-card"><span>${icon('file')}</span><div><b>${esc(f.name)}</b><small>${f.image?'图片':(f.text?.length||0)+' 字'}${f.truncated?' · 部分内容':''}</small></div>${remove?`<button type="button" data-remove="${esc(f.id)}" aria-label="移除 ${esc(f.name)}">×</button>`:''}</div>`;}
 function capture(){const p=$('#prompt');if(p&&state)drafts.set(state.activeId,p.value);}
 function render(){if(!state)return;capture();const focused=$('#prompt')===document.activeElement,start=$('#prompt')?.selectionStart;appearance();if(!state.introComplete){welcome();return;}
  const current=bot(),title=page==='chat'?current?.name||'Fishbot':({bots:'Bots',history:'聊天记录',memory:'长期记忆',settings:'我的 Fishbot'})[page];
  $('#app').innerHTML=`<header class="top"><button class="icon" id="open-bots" aria-label="切换 Bot">${icon(page==='chat'?'menu':'back')}</button>${page==='chat'?avatar(current):''}<div class="top-title"><b>${esc(title)}</b><small>${page==='chat'?(engine.busy&&engine.activeId===current?.id?'正在回复…':current?.type==='group'?current.memberIds.length+' 位成员 · 各有分工':'FISHBOT · 随时陪伴'):'独立运行 · 保存在本机'}</small></div>${page==='chat'?`<button class="icon" id="bot-options" aria-label="Bot 设置">${icon('more')}</button>`:`<button class="icon" id="toggle-theme" aria-label="切换昼夜">${icon('sun')}</button>`}</header><main class="content" id="content">${page==='chat'?chat(current):page==='bots'?botsPage():page==='history'?history():page==='memory'?memories():settings()}</main><nav class="bottom" aria-label="主导航">${[['chat','对话','chat'],['bots','Bots','bots'],['memory','记忆','memory'],['settings','设置','settings']].map(([id,name,glyph])=>`<button data-page="${id}" class="${page===id?'active':''}" aria-current="${page===id?'page':'false'}">${icon(glyph)}<span>${name}</span></button>`).join('')}</nav>`;
  bind();if(focused&&$('#prompt')){$('#prompt').focus({preventScroll:true});$('#prompt').setSelectionRange(start,start);}const messages=$('#messages');if(messages)messages.scrollTop=messages.scrollHeight;
 }
 function chat(b){const entries=b.messages||[];return `<div class="conversation"><div class="messages" id="messages">${entries.length?`<div class="day">${new Date(entries.at(-1).at).toLocaleDateString('zh-CN')}</div>${entries.map(m=>`<article class="message ${m.role} ${m.error?'error':''}" data-message="${esc(m.id)}">${b.type==='group'&&m.role==='assistant'?`<div class="speaker">${avatar(state.bots.find(b=>b.id===m.botId))}<b>${esc(m.speaker)}</b>${m.summary?'<small>应邀总结</small>':''}</div>`:''}${m.attachments?.length?`<div class="file-list">${m.attachments.map(f=>card(f)).join('')}</div>`:''}<div class="message-copy">${esc(m.content)}</div><div class="message-meta"><time>${date(m.at)}</time>${m.role==='assistant'&&!m.error?`<button data-copy="${esc(m.id)}">复制</button><button data-remember="${esc(m.id)}">记住</button>`:''}</div></article>`).join('')}`:`<div class="empty-chat"><img src="whale.svg" alt="小鲸"><h2>${esc(b.name)}</h2><p>${b.type==='group'?'一起聊聊，让不同的想法在这里相遇。':'想法、计划、生活中的小事，随时和我聊聊。'}</p><div class="suggestions">${['帮我安排今天','一起讨论一个想法','看看这份文件'].map(t=>`<button data-suggestion="${t}">${t}</button>`).join('')}</div></div>`}${engine.busy&&engine.activeId===b.id?`<div class="thinking">${[...engine.speakers].map(id=>state.bots.find(b=>b.id===id)?.name).filter(Boolean).map(esc).join('、')||'Fishbot'} 正在思考 <span class="typing-dots">···</span></div>`:''}</div><div class="composer-wrap"><form id="composer" class="composer">${files().length?`<div class="file-list">${files().map(f=>card(f,true)).join('')}</div>`:''}${reading?'<div class="file-reading" role="status">正在本机读取文件…</div>':''}<textarea id="prompt" rows="2" aria-label="发送消息" placeholder="和 ${esc(b.name)} 说点什么…" maxlength="30000">${esc(drafts.get(b.id)||'')}</textarea><div class="composer-bottom"><button type="button" class="icon" id="add-file" aria-label="添加文件" ${reading?'disabled':''}>${icon('plus')}</button><span class="model">${esc(C.connection(state,b.type==='group'?state.bots.find(x=>x.id===state.supervisorId):b).model||'先连接 API')}</span>${engine.busy?`<button type="button" id="stop" class="send" aria-label="停止回复">${icon('stop')}</button>`:`<button class="send" aria-label="发送">${icon('arrow')}</button>`}</div></form></div></div>`;}
 function botsPage(){const q=filter.toLowerCase();return `<section class="page"><div class="page-heading"><div><h1>各有所长</h1><p class="subtitle">一个主管，和你自己的小团队。</p></div><button class="icon" id="new-bot" aria-label="新建 Bot">${icon('plus')}</button></div><input class="search" id="bot-search" type="search" aria-label="搜索 Bot" placeholder="搜索 Bots" value="${esc(filter)}"><div id="bot-rows">${state.bots.filter(b=>b.name.toLowerCase().includes(q)).map(b=>botRow(b)).join('')}</div><div class="button-row"><button class="secondary" id="new-group">创建讨论群</button><button class="secondary" data-page="history">聊天记录</button></div></section>`;}
 function botRow(b){const last=b.messages.at(-1);return `<button class="row ${b.id===state.activeId?'selected':''}" data-bot="${esc(b.id)}">${avatar(b)}<span class="row-copy"><b>${esc(b.name)}${b.id===state.supervisorId?' · 主管':''}</b><small>${esc(b.type==='group'?b.memberIds.length+' 位成员':b.job||last?.content||'开始一段新对话')}</small></span>${last?`<time>${date(last.at)}</time>`:''}</button>`;}
 function history(){const records=state.bots.filter(b=>b.messages.some(m=>m.role==='user')).sort((a,b)=>(b.messages.at(-1)?.at||0)-(a.messages.at(-1)?.at||0));return `<section class="page"><h1>聊过的，都在</h1><p class="subtitle">这里只保留你与 Bot 的问答。</p>${records.map(botRow).join('')||'<p class="empty">聊完第一段对话后，会出现在这里。</p>'}</section>`;}
 function memories(){const selected=state.memories.find(m=>m.id===selectedMemory),list=memoryTab==='map'&&selected?[selected]:state.memories.slice().reverse();return `<section class="page"><div class="page-heading"><h1>记得你说过的</h1><button class="icon" id="new-memory" aria-label="添加记忆">${icon('plus')}</button></div><p class="subtitle">本机记忆供所有 Bot 使用，新建或删除聊天都不会清除。<br>可在回复下方点「记住」，或发送「记住：…」。</p><div class="segmented"><button data-memory-tab="list" class="${memoryTab==='list'?'active':''}">时间线 · ${state.memories.length}</button><button data-memory-tab="map" class="${memoryTab==='map'?'active':''}">来源关系</button></div>${memoryTab==='map'?mapMarkup():''}${list.map(m=>`<article class="memory-item"><p>${esc(m.text)}</p><small>${date(m.at)} · ${esc(state.bots.find(b=>b.id===m.botId)?.name||'手动保存')}</small><button data-forget="${esc(m.id)}">忘记</button></article>`).join('')||'<p class="empty">还没有保存的记忆。<br>称呼、偏好、习惯，都可以留在这里。</p>'}</section>`;}
 function mapMarkup(){const all=C.memoryGraph(state),mem=all.nodes.filter(n=>n.type==='memory').slice(-12),sources=all.nodes.filter(n=>n.type==='bot'&&all.links.some(l=>l.source===n.id&&mem.some(n=>n.id===l.target))),nodes=[...sources,...mem],points=new Map(nodes.map((n,i)=>[n.id,{x:160+Math.cos(i/nodes.length*Math.PI*2-1.57)*115,y:145+Math.sin(i/nodes.length*Math.PI*2-1.57)*100}]));return `<svg class="memory-map" viewBox="0 0 320 290" role="img" aria-label="记忆与来源 Bot 的真实关联">${all.links.filter(l=>points.has(l.source)&&points.has(l.target)).map(l=>{const a=points.get(l.source),b=points.get(l.target);return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/>`;}).join('')}${nodes.map(n=>{const p=points.get(n.id);return `<g class="map-node ${n.type==='bot'?'source':''} ${selectedMemory===n.id?'selected':''}" data-node="${esc(n.id)}" tabindex="0" role="button" aria-label="${esc(n.label)}"><circle cx="${p.x}" cy="${p.y}" r="${n.type==='bot'?13:8}"/><text x="${p.x}" y="${p.y+25}" text-anchor="middle">${esc(n.label.slice(0,7))}</text></g>`;}).join('')}</svg><p class="hint">最多显示最近12条记忆，连线只表示实际保存来源。</p>`;}
 function settings(){return `<section class="page"><h1>让 Fishbot 更懂你</h1><p class="subtitle">手机独立运行，API Key 保存在 ${B.native?'iOS 钥匙串':'当前设备'}。</p><form id="settings-form"><section class="settings-card"><h2>模型连接</h2><button type="button" class="pill" id="deepseek">DeepSeek 一键预置</button><label class="field">API 地址<input name="baseURL" type="url" value="${esc(state.config.baseURL)}" required></label><label class="field">模型名称<input name="model" value="${esc(state.config.model)}" required maxlength="160"></label><label class="field">API Key<input name="apiKey" type="password" placeholder="${state.config.keySet?'已保存，留空沿用':'填入你的 Key'}" autocomplete="off"></label><div class="button-row"><button type="button" class="secondary" id="test-api">测试连接</button><button class="primary">保存设置</button></div><p class="hint" id="api-feedback">Key 只发给你指定的 API；多 Bot 讨论会增加调用量。</p></section><section class="settings-card"><h2>显示与阅读</h2><label class="setting-row">夜间模式<input name="dark" type="checkbox" ${state.config.theme==='dark'?'checked':''}></label><label class="setting-row">模型支持图片<input name="vision" type="checkbox" ${state.config.vision?'checked':''}></label><label class="setting-row">减少动画<input name="reducedMotion" type="checkbox" ${state.config.reducedMotion?'checked':''}></label><p class="hint">手机端支持问答、群聊、文件和本机记忆。桌面观察、鼠标控制及内置 Hindsight 服务需在 Windows 版使用。</p></section></form><section class="settings-card"><h2>数据与备份</h2><p>聊天和记忆保存在手机上。导出不包含 API Key；重装前建议先备份。</p><div class="button-row"><button class="secondary" id="export-data">导出备份</button><button class="secondary" id="import-data">导入备份</button></div></section><p class="hint">Fishbot iOS · 0.1.0 · 无需电脑保持开机</p></section>`;}
 function sheet(title,body){$('#overlay').innerHTML=`<div class="sheet-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="sheet-header"><h2>${esc(title)}</h2><button class="icon" id="close-sheet" aria-label="关闭">${icon('close')}</button></header><div class="sheet-body">${body}</div></section></div>`;$('#close-sheet').onclick=closeSheet;$('.sheet-backdrop').onclick=e=>{if(e.target===$('.sheet-backdrop'))closeSheet();};}
 function closeSheet(){$('#overlay').innerHTML='';}
 function confirmAction(title,text,run){sheet(title,`<p class="hint">${esc(text)}</p><div class="button-row"><button class="secondary" id="cancel-action">取消</button><button class="danger" id="confirm-action">确认</button></div>`);$('#cancel-action').onclick=closeSheet;$('#confirm-action').onclick=()=>attempt(async()=>{await run();closeSheet();await save();render();});}
 function openBotOptions(b){if(engine.busy){toast('请先停止或等待当前回复完成。');return;}if(b.type==='group'){openGroup(b);return;}
  sheet(b.name+' · 设置',`<form id="profile-form"><div class="profile-preview">${avatar(b)}<span class="hint">名称、人格和职责都由你决定。</span></div><label class="field">名称<input name="name" value="${esc(b.name)}" maxlength="40" required></label><label class="field">职责<input name="job" value="${esc(b.job||'')}" placeholder="例如：资料研究、学习规划" maxlength="3000"></label><label class="field">人格<textarea name="personality" rows="3" maxlength="6000">${esc(b.personality)}</textarea></label>${b.id!==state.supervisorId?`<label class="field">头像形状<select name="shape">${C.shapes.map((s,i)=>`<option value="${s}" ${b.shape===s?'selected':''}>${['圆形','圆角方形','菱形','六边形'][i]}</option>`).join('')}</select></label>`:''}<div class="section-label">头像颜色</div><div class="color-options">${C.colors.map(c=>`<button type="button" class="color-choice ${c}" data-color="${c}" aria-label="${c}" aria-pressed="${b.color===c}"></button>`).join('')}</div><label class="setting-row">使用默认 API<input name="inheritAPI" type="checkbox" ${b.inheritAPI!==false?'checked':''}></label><details ${b.inheritAPI===false?'open':''}><summary class="hint">独立 API</summary><label class="field">API 地址<input name="baseURL" type="url" value="${esc(b.baseURL)}"></label><label class="field">模型<input name="model" value="${esc(b.model)}"></label><label class="field">API Key<input name="apiKey" type="password" placeholder="${b.keySet?'已保存，留空沿用':'独立 API 的 Key'}" autocomplete="off"></label><label class="setting-row">清除独立 Key<input name="clearKey" type="checkbox"></label></details><div class="button-row"><button class="primary">保存 Bot</button></div></form><div class="button-row"><button class="secondary" id="clear-chat">清空聊天</button>${b.id!==state.supervisorId?'<button class="danger" id="delete-bot">删除 Bot</button>':''}</div>`);
  let color=b.color;document.querySelectorAll('[data-color]').forEach(el=>el.onclick=()=>{color=el.dataset.color;document.querySelectorAll('[data-color]').forEach(x=>x.setAttribute('aria-pressed',String(x===el)));});
  $('#profile-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const f=e.target,d=Object.fromEntries(new FormData(f)),next=C.profile(b,{...d,inheritAPI:f.inheritAPI.checked,color});if(b.keySet&&!d.apiKey.trim()&&!f.clearKey.checked&&new URL(next.baseURL).origin!==new URL(b.baseURL).origin)throw new Error('更换服务地址后请填写对应的新 Key，或清除旧 Key。');if(d.apiKey.trim()||f.clearKey.checked){await B.setSecret('bot-'+b.id,d.apiKey.trim());next.keySet=!!d.apiKey.trim();}delete next.apiKey;Object.assign(b,next);closeSheet();await save();render();});};bindManagement(b);}
 function bindManagement(b){$('#clear-chat').onclick=()=>confirmAction('清空聊天与上下文','只清除这个聊天的记录和附件，保留 Bot 配置及共享记忆。',async()=>{C.clear(state,b.id);pending.delete(b.id);drafts.delete(b.id);});if($('#delete-bot'))$('#delete-bot').onclick=()=>confirmAction(b.type==='group'?'删除群聊':'删除 Bot',b.type==='group'?'群聊记录将删除，成员与记忆保留。':'Bot、聊天及其独立 Key 将删除，共享记忆保留。',async()=>{await B.setSecret('bot-'+b.id,'');C.removeBot(state,b.id);pending.delete(b.id);drafts.delete(b.id);});}
 function openGroup(existing){if(engine.busy){toast('请先等待当前回复完成。');return;}const members=state.bots.filter(b=>b.type!=='group'&&b.id!==state.supervisorId);sheet(existing?'管理群聊':'创建讨论群',`<form id="group-form"><label class="field">群名称<input name="name" maxlength="40" value="${esc(existing?.name||'讨论小组')}" required></label><p class="hint">主管自动加入。成员可共用默认 API，也可分别配置。</p>${members.map(b=>`<label class="member-choice">${avatar(b)}<span>${esc(b.name)}</span><input type="checkbox" name="members" value="${esc(b.id)}" ${!existing||existing.memberIds.includes(b.id)?'checked':''}></label>`).join('')||'<p class="empty">先在 Bots 页面新建一位子 Bot。</p>'}<label class="field">讨论轮数<select name="rounds"><option value="1">一轮</option><option value="2" ${existing?.rounds===2?'selected':''}>两轮，第二轮互相回应</option></select></label><label class="setting-row">同时发言<input name="parallel" type="checkbox" ${existing?.parallel!==false?'checked':''}></label><div class="button-row"><button class="primary" ${!members.length?'disabled':''}>${existing?'保存群聊':'创建群聊'}</button></div></form>${existing?'<div class="button-row"><button class="secondary" id="clear-chat">清空聊天</button><button class="danger" id="delete-bot">删除群聊</button></div>':''}`);$('#group-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const f=e.target,data=new FormData(f),ids=data.getAll('members');if(!ids.length)throw new Error('至少加入一位子 Bot。');if(existing)Object.assign(existing,{name:String(data.get('name')).trim(),memberIds:[state.supervisorId,...ids],rounds:Number(data.get('rounds')),parallel:f.parallel.checked});else C.group(state,{name:data.get('name'),memberIds:ids,rounds:Number(data.get('rounds')),parallel:f.parallel.checked});closeSheet();page='chat';await save();render();});};if(existing)bindManagement(existing);}
 function welcome(){const flipped=!!document.querySelector('.welcome-card.flipped');$('#app').innerHTML=`<section class="onboarding"><button class="welcome-card ${flipped?'flipped':''}" id="welcome-card"><img src="whale.svg" alt="小鲸"><h1>命名你的<br>个人生活助理</h1><p>轻点卡片，为它起个名字。</p></button><small>一个属于你的随身空间</small></section>`;$('#welcome-card').onclick=()=>{$('#welcome-card').outerHTML=`<form class="welcome-card flipped" id="name-form"><img src="whale.svg" alt=""><label class="field">你想怎么称呼它？<input name="name" maxlength="40" required value="Fishbot" aria-label="助理名称"></label><button class="primary">开始陪伴</button></form>`;$('#name-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{state.config.name=e.target.elements.namedItem('name').value.trim()||'Fishbot';state.introComplete=true;await save();render();toast('先在设置中填写自己的 API Key，就可以开始聊天。');});};};}
 async function send(){const p=$('#prompt'),text=p?.value.trim()||'',id=state.activeId,attached=files(),target=bot(),before=target.messages.length;if(reading){toast('文件仍在读取，请稍等。');return;}if(!text&&!attached.length)return;if(engine.busy){toast('请先等待回复或停止。');return;}if(p)p.value='';drafts.set(id,'');pending.delete(id);try{const task=engine.run(id,text,attached);render();await task;}catch(e){if(target.messages.length===before){drafts.set(id,text);pending.set(id,attached);}toast(e.name==='AbortError'?'已停止回复。':e.message);}render();}

 async function addFiles(input){const id=state.activeId;if(reading)return;const current=pending.get(id)||[],space=5-current.length;if(space<1){toast('每条最多5个文件。');return;}reading=true;render();try{for(const f of [...input].slice(0,space)){try{const result=await FishbotReadFile(f);if(result.image&&!state.config.vision)throw new Error('当前未开启图片理解，请在设置中确认模型支持。');if(state.bots.some(b=>b.id===id)){const list=pending.get(id)||[];list.push({...result,id:C.uuid()});pending.set(id,list);}}catch(e){toast(f.name+'：'+e.message);}}if(input.length>space)toast('最多添加5个文件，剩余文件请分批发送。');}finally{reading=false;render();}}
 async function select(id){capture();state.activeId=id;page='chat';closeSheet();await save();render();}
 function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{capture();page=b.dataset.page;filter='';render();});$('#open-bots').onclick=()=>{capture();page=page==='chat'?'bots':'chat';render();};if($('#toggle-theme'))$('#toggle-theme').onclick=()=>attempt(async()=>{state.config.theme=state.config.theme==='dark'?'light':'dark';await save();render();});document.querySelectorAll('[data-bot]').forEach(b=>b.onclick=()=>attempt(()=>select(b.dataset.bot)));
  if($('#composer')){$('#composer').onsubmit=e=>{e.preventDefault();send();};const input=$('#prompt');input.oninput=e=>{drafts.set(state.activeId,e.target.value);input.style.height='auto';input.style.height=Math.min(135,input.scrollHeight)+'px';};let composing=false;input.oncompositionstart=()=>composing=true;input.oncompositionend=()=>composing=false;input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!composing&&!e.isComposing&&e.keyCode!==229){e.preventDefault();if(!e.repeat)send();}};$('#add-file').onclick=()=>$('#file-picker').click();$('#bot-options').onclick=()=>openBotOptions(bot());if($('#stop'))$('#stop').onclick=()=>engine.stop();document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{capture();pending.set(state.activeId,files().filter(f=>f.id!==b.dataset.remove));render();});document.querySelectorAll('[data-suggestion]').forEach(b=>b.onclick=()=>{if(b.dataset.suggestion.includes('文件'))$('#file-picker').click();else{$('#prompt').value=b.dataset.suggestion;drafts.set(state.activeId,b.dataset.suggestion);$('#prompt').focus();}});document.querySelectorAll('[data-remember]').forEach(b=>b.onclick=()=>attempt(async()=>{const m=bot().messages.find(m=>m.id===b.dataset.remember);C.remember(state,m.content,{botId:m.botId||bot().id,messageId:m.id});await save();toast('已保存到共享记忆。');}));document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>attempt(async()=>{const text=bot().messages.find(m=>m.id===b.dataset.copy).content;if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else await B.share(text,'回复.txt');toast('已复制或打开分享。');}));}
  if($('#new-bot'))$('#new-bot').onclick=()=>attempt(async()=>{if(engine.busy)throw new Error('请先等待回复完成。');const b=C.createBot(state);await save();page='chat';render();openBotOptions(b);});if($('#new-group'))$('#new-group').onclick=()=>openGroup();if($('#bot-search'))$('#bot-search').oninput=e=>{filter=e.target.value;const q=filter.toLowerCase();$('#bot-rows').innerHTML=state.bots.filter(b=>b.name.toLowerCase().includes(q)).map(botRow).join('');$('#bot-rows').querySelectorAll('[data-bot]').forEach(b=>b.onclick=()=>attempt(()=>select(b.dataset.bot)));};
  if($('#new-memory'))$('#new-memory').onclick=()=>{sheet('记住一件事','<form id="memory-form"><label class="field">偏好、习惯或重要信息<textarea name="text" rows="5" maxlength="6000" required></textarea></label><button class="primary">保存记忆</button></form>');$('#memory-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{C.remember(state,e.target.text.value);await save();closeSheet();render();});};};document.querySelectorAll('[data-memory-tab]').forEach(b=>b.onclick=()=>{memoryTab=b.dataset.memoryTab;selectedMemory=null;render();});document.querySelectorAll('[data-forget]').forEach(b=>b.onclick=()=>confirmAction('忘记这条信息','这条记忆将移除，聊天记录仍保留。',async()=>{state.memories=state.memories.filter(m=>m.id!==b.dataset.forget);}));document.querySelectorAll('[data-node]').forEach(n=>{const choose=()=>{if(state.memories.some(m=>m.id===n.dataset.node)){selectedMemory=n.dataset.node;render();}};n.onclick=choose;n.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')choose();};});if($('#settings-form'))bindSettings();
 }
 function bindSettings(){const f=$('#settings-form');$('#deepseek').onclick=()=>{f.baseURL.value=C.defaults.baseURL;f.model.value=C.defaults.model;};async function draftSettings(){const baseURL=f.baseURL.value.trim(),model=f.model.value.trim(),key=f.apiKey.value.trim();C.endpoint(baseURL);if(!model)throw new Error('请填写模型名称。');if(state.config.keySet&&!key&&new URL(baseURL).origin!==new URL(state.config.baseURL).origin)throw new Error('更换 API 服务后，请填写对应的新 Key。');return {baseURL,model,key};}
  f.onsubmit=e=>{e.preventDefault();attempt(async()=>{const d=await draftSettings();if(d.key){await B.setSecret('global',d.key);state.config.keySet=true;}Object.assign(state.config,{baseURL:d.baseURL,model:d.model,theme:f.dark.checked?'dark':'light',vision:f.vision.checked,reducedMotion:f.reducedMotion.checked});await save();render();toast('设置已保存。');});};$('#test-api').onclick=()=>attempt(async()=>{const d=await draftSettings(),key=d.key||await B.getSecret('global');if(!key)throw new Error('先填写 API Key。');const button=$('#test-api');button.disabled=true;$('#api-feedback').textContent='正在测试，会产生一次 API 调用…';try{const c={baseURL:d.baseURL,model:d.model},r=await B.request(C.endpoint(c.baseURL),{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+key},body:JSON.stringify(C.body(c,[{role:'user',content:'连接测试，只回复 OK。'}]))});if(!r.ok)throw new Error('API 返回 HTTP '+r.status+'，请检查 Key、模型和地址。');const data=await r.json();if(!data.choices?.[0]?.message?.content)throw new Error('没有收到有效回复。');$('#api-feedback').textContent='连接成功。记得点保存设置。';}finally{button.disabled=false;}});
  $('#export-data').onclick=()=>attempt(async()=>{const text=JSON.stringify(C.exportData(state),null,2),name='Fishbot-'+new Date().toISOString().slice(0,10)+'.json';if(B.native){await B.share(text,name);return;}const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);});$('#import-data').onclick=()=>{if(engine.busy){toast('先停止当前回复再导入。');return;}const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=()=>attempt(async()=>{const file=input.files[0];if(!file)return;if(file.size>30*1024*1024)throw new Error('备份文件太大。');const imported=C.hydrate(JSON.parse(await file.text()));confirmAction('导入备份','将替换本机聊天和记忆。备份不包含 Key，导入后请核对模型连接。',async()=>{state=imported;state.config.keySet=!!await B.getSecret('global');for(const b of state.bots)if(b.type!=='group')b.keySet=!!await B.getSecret('bot-'+b.id);engine.state=state;});});input.click();};
 }
 $('#file-picker').onchange=async e=>{const selected=[...e.target.files];e.target.value='';await addFiles(selected);};document.addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('Files'))e.preventDefault();});document.addEventListener('drop',e=>{if([...e.dataTransfer.types].includes('Files')){e.preventDefault();if(page==='chat')addFiles([...e.dataTransfer.files]);}});
 function viewport(){const v=window.visualViewport;document.documentElement.style.setProperty('--app-height',Math.round(v?.height||innerHeight)+'px');document.body.classList.toggle('keyboard-open',!!v&&innerHeight-v.height>120);}
 window.visualViewport?.addEventListener('resize',viewport);window.addEventListener('resize',viewport);viewport();
 (async()=>{try{state=C.hydrate(await B.load());engine=new FishbotEngine(state,{save,change:()=>render()});render();}catch(e){$('#boot-status').textContent=e.message+'。请保留现有数据，检查存储后重新打开。';}})();
})();
